nextflow_process {

    name "Test Process RPBP_ESTIMATEMETAGENEBAYESFACTORS"
    script "../main.nf"
    process "RPBP_ESTIMATEMETAGENEBAYESFACTORS"

    tag "modules"
    tag "modules_nfcore"
    tag "rpbp"
    tag "rpbp/estimatemetagenebayesfactors"

    test("homo_sapiens chr20 - metagene bayes factors") {

        when {
            process {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:true, strandedness:'forward' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/rpbp/SRX11780888_chr20.metagene-profile.csv.gz", checkIfExists: true)
                ])
                """
            }
        }

        then {
            def bayes_factors = file(process.out.bayes_factors[0][1])
            def rows = path(process.out.bayes_factors[0][1]).linesGzip
            def header = rows[0].split(",")
            // The p_periodic_*, p_nonperiodic_*, and bayes_factor_* columns are MCMC
            // estimates whose floats differ between the conda and container toolchains;
            // snapshot only the deterministic input-derived columns.
            def stable_cols = ["offset", "profile_sum", "profile_peak", "length"].collect { name -> header.findIndexOf { it == name } }
            def stable = rows.collect { line -> def fields = line.split(","); stable_cols.collect { fields[it] }.join(",") }.join("\n")
            def stable_md5 = java.security.MessageDigest.getInstance("MD5").digest(stable.bytes).encodeHex().toString()
            assertAll(
                { assert process.success },
                { assert snapshot(
                    bayes_factors.name,
                    rows.size(),
                    rows[0],
                    stable_md5,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("homo_sapiens chr20 - metagene bayes factors - stub") {

        options '-stub'

        when {
            process {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:true, strandedness:'forward' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/rpbp/SRX11780888_chr20.metagene-profile.csv.gz", checkIfExists: true)
                ])
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

